-- State transitions declared for Quotation: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION selling.quotations_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('accepted', 'cancelled'), ('accepted', 'ordered'), ('cancelled', 'draft'), ('draft', 'accepted'), ('draft', 'cancelled'), ('draft', 'sent'), ('rejected', 'draft'), ('sent', 'accepted'), ('sent', 'cancelled'), ('sent', 'draft'), ('sent', 'rejected'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: quotations.status % -> %', OLD."status", NEW."status"
            USING ERRCODE = 'check_violation', COLUMN = 'status', CONSTRAINT = 'tg_quotations__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS quotations_status_transition_check ON selling.quotations;
CREATE TRIGGER quotations_status_transition_check
    BEFORE UPDATE OF "status" ON selling.quotations
    FOR EACH ROW EXECUTE FUNCTION selling.quotations_status_transition_check();
